using System;

namespace BikeShop.Models
{
    // One customer.  Plain properties only: the form checks what the user typed
    // before it fills these in.
    public class Customer
    {
        public int CustomerID { get; set; }
        public string FirstName { get; set; }
        public string LastName { get; set; }
        public string Phone { get; set; }
        public string Email { get; set; }
        public DateTime DateJoined { get; set; }

        public string FullName
        {
            get { return FirstName + " " + LastName; }
        }
    }
}

using System;
using System.Data;
using System.Data.SqlClient;
using BikeShop.Models;

namespace BikeShop.Data
{
    public static class CustomerData
    {
        #region Search
        // Customers whose name or phone contains the search text.
        public static DataTable Search(string searchText)
        {
            return Db.GetTable("usp_Customer_Search",
                Db.P("@SearchText", searchText));
        }
        #endregion

        #region GetByID
        // One customer as an object, or null if there is no customer with that
        // ID.
        public static Customer GetByID(int customerID)
        {
            DataTable table = Db.GetTable("usp_Customer_GetByID",
                Db.P("@CustomerID", customerID));
            if (table.Rows.Count == 0)
            {
                return null;
            }

            DataRow row = table.Rows[0];
            Customer customer = new Customer();
            customer.CustomerID = (int)row["CustomerID"];
            customer.FirstName = (string)row["FirstName"];
            customer.LastName = (string)row["LastName"];
            customer.Phone = (string)row["Phone"];
            if (row["Email"] == DBNull.Value)
            {
                customer.Email = null;
            }
            else
            {
                customer.Email = (string)row["Email"];
            }
            customer.DateJoined = (DateTime)row["DateJoined"];
            return customer;
        }
        #endregion

        #region Add
        // Saves a new customer.  Returns "" if it worked, or the sentence to
        // show the user.
        public static string Add(Customer customer)
        {
            SqlParameter newID = Db.Out("@NewCustomerID");
            string message = Db.Run("usp_Customer_Add",
                Db.P("@FirstName", customer.FirstName),
                Db.P("@LastName", customer.LastName),
                Db.P("@Phone", customer.Phone),
                Db.P("@Email", customer.Email),
                newID);
            if (message == "")
            {
                customer.CustomerID = (int)newID.Value;
            }
            return message;
        }
        #endregion

        #region Update
        // Saves changes to an existing customer.  Returns "" if it worked.
        public static string Update(Customer customer)
        {
            return Db.Run("usp_Customer_Update",
                Db.P("@CustomerID", customer.CustomerID),
                Db.P("@FirstName", customer.FirstName),
                Db.P("@LastName", customer.LastName),
                Db.P("@Phone", customer.Phone),
                Db.P("@Email", customer.Email));
        }
        #endregion

        #region Delete
        // The procedure refuses if the customer has bookings.  Returns "" if it
        // worked.
        public static string Delete(int customerID)
        {
            return Db.Run("usp_Customer_Delete",
                Db.P("@CustomerID", customerID));
        }
        #endregion
    }
}

using System;
using System.Text;
using System.Windows.Forms;

namespace BikeShop
{
    // Small helpers every grid uses.  Call Tidy straight after you set a grid's
    // DataSource.
    public static class Grid
    {
        #region Tidy
        // Hides the ID columns (the user never needs a number) and turns column
        // names into plain headers.
        public static void Tidy(DataGridView grid,
            params string[] hiddenColumns)
        {
            foreach (string name in hiddenColumns)
                if (grid.Columns.Contains(name)) grid.Columns[name].Visible =
                    false;

            foreach (DataGridViewColumn column in grid.Columns)
            {
                column.HeaderText = Words(column.Name);
                if (column.ValueType == typeof(decimal) && IsMoney(column.Name))
                {
                    column.DefaultCellStyle.Format = "£#,##0.00";
                    column.DefaultCellStyle.Alignment =
                        DataGridViewContentAlignment.MiddleRight;
                }
                else if (column.ValueType == typeof(DateTime))
                {
                    column.DefaultCellStyle.Format = "ddd d MMM yyyy";
                    if (column.Name.Contains("Time"))
                    {
                        column.DefaultCellStyle.Format = "HH:mm";
                    }
                }
            }
            grid.ClearSelection();
        }

        private static bool IsMoney(string name)
        {
            return name.Contains("Price") || name.Contains("Rate")
                || name.Contains("Cost") || name.Contains("Income")
                || name.Contains("Deposit") || name.Contains("Total")
                    || name.Contains("Paid");
        }
        #endregion

        #region Words
        // "BikeDescription" → "Bike description", "QtyInStock" → "Qty in
        // stock", "Mechanic" → "Mechanic"
        public static string Words(string columnName)
        {
            StringBuilder words = new StringBuilder();
            for (int i = 0; i < columnName.Length; i++)
            {
                char c = columnName[i];
                if (i > 0 && char.IsUpper(c) && char.IsLower(columnName[i - 1]))
                {
                    words.Append(' ');
                    words.Append(char.ToLower(c));
                }
                else
                {
                    words.Append(c);
                }
            }
            return words.ToString();
        }
        #endregion

        #region Selected
        // The hidden ID of the picked row (0 when nothing is picked).
        public static int SelectedID(DataGridView grid, string idColumn)
        {
            if (grid.SelectedRows.Count == 0) return 0;
            return Convert.ToInt32(grid.SelectedRows[0].Cells[idColumn].Value);
        }

        // A text value from the picked row ("" when nothing is picked).
        public static string SelectedText(DataGridView grid, string column)
        {
            if (grid.SelectedRows.Count == 0) return "";
            return Convert.ToString(grid.SelectedRows[0].Cells[column].Value);
        }
        #endregion
    }
}

// Fills the grid from the database.  Called when the form opens, when
// the search text changes,
// and after every add, edit or delete, so the grid always shows what
// the database holds.
private void LoadCustomers()
{
    dgvCustomers.DataSource =
        CustomerData.Search(txtSearch.Text.Trim());
    // hide the ID, give the headers plain words
    Grid.Tidy(dgvCustomers, "CustomerID");
}

// Edit and Delete only make sense once a row is picked.
private void dgvCustomers_SelectionChanged(object sender, EventArgs e)
{
    bool picked = dgvCustomers.SelectedRows.Count > 0;
    btnEdit.Enabled = picked;
    btnDelete.Enabled = picked;
    ShowBookings();
}

// The lower grid shows the picked customer's bookings: two tables on
// one screen.
private void ShowBookings()
{
    if (dgvCustomers.SelectedRows.Count == 0)
    {
        dgvBookings.DataSource = null;
        return;
    }

    dgvBookings.DataSource =
        AppointmentData.GetForCustomer(Grid.SelectedID(dgvCustomers,
        "CustomerID"));
    Grid.Tidy(dgvBookings, "AppointmentID");
}

private void btnAdd_Click(object sender, EventArgs e)
{
    // 0 means "a new customer"
    frmCustomerEdit edit = new frmCustomerEdit(0);
    if (edit.ShowDialog(this) == DialogResult.OK)
    {
        LoadCustomers();
    }
}

private void btnEdit_Click(object sender, EventArgs e)
{
    frmCustomerEdit edit =
        new frmCustomerEdit(Grid.SelectedID(dgvCustomers,
        "CustomerID"));
    if (edit.ShowDialog(this) == DialogResult.OK)
    {
        LoadCustomers();
    }
}

private void dgvCustomers_CellDoubleClick(object sender,
    DataGridViewCellEventArgs e)
{
    if (e.RowIndex >= 0)
    {
        btnEdit_Click(sender, e);
    }
}

private void btnDelete_Click(object sender, EventArgs e)
{
    string name = Grid.SelectedText(dgvCustomers, "FullName");
    if (!Msg.Ask("Delete " + name + "? This cannot be undone."))
    {
        return;
    }

    string message =
        CustomerData.Delete(Grid.SelectedID(dgvCustomers,
        "CustomerID"));
    if (message != "")
    {
        // the database refuses when the customer has bookings or sales,
        // and says so
        Msg.Problem(message);
        return;
    }
    LoadCustomers();
}

